export interface ConnectorConfig {
  /** Shopify client secret for HMAC-SHA256 verification (env: SHOPIFY_CLIENT_SECRET) */
  shopifyClientSecret: string
  /** Airtable API key for Bearer authentication (env: AIRTABLE_API_KEY) */
  airtableApiKey: string
  /** Airtable base ID (e.g., appXXXXXXXXXXXXXX) */
  airtableBaseId: string
  /** Airtable table name or ID */
  airtableTableNameOrId: string
  /** Deduplication store for order_id + hmac pairs */
  dedupStore: DedupStore
  /** Injected fetch for testing (defaults to global fetch) */
  fetch?: typeof fetch
  /** Maximum retry attempts after initial request (default: 3) */
  maxRetries?: number
  /** Base retry delay in ms (default: 1000) */
  baseRetryDelayMs?: number
  /** Optional HMAC verification function (defaults to Web Crypto API) */
  verifyHmac?: (rawBody: string, hmacHeader: string, secret: string) => Promise<boolean>
}

export interface DedupStore {
  /** Check if a deduplication key has been seen */
  has(key: string): Promise<boolean>
  /** Record a deduplication key as seen */
  add(key: string): Promise<void>
}

/** Shopify orders/paid webhook payload (UCP format) */
export interface ShopifyOrderPaidPayload {
  id: string
  label: string
  currency: string
  totals: Array<{ type: string; display_text: string; amount: number }>
  line_items: unknown[]
  fulfillment: unknown
  adjustments: unknown[]
  ucp: unknown
  /** Raw request body for HMAC verification (added by webhook handler) */
  _rawBody?: string
  /** Request headers for HMAC and webhook ID (added by webhook handler) */
  _headers?: Record<string, string>
}

export interface HandleResult {
  /** Airtable record IDs returned by upsert */
  airtableRecordIds: string[]
  /** True if at least one record was created */
  created: boolean
  /** True if at least one record was updated */
  updated: boolean
  /** True if the webhook was deduplicated and not processed */
  deduplicated: boolean
}

interface AirtableUpsertResponse {
  records: Array<{ id: string; createdTime: string; fields: Record<string, unknown> }>
  updatedRecords: string[][]
  createdRecords: string[]
}

function findTotalAmount(payload: ShopifyOrderPaidPayload, type: string): number | null {
  const total = payload.totals.find(t => t.type === type)
  return total ? total.amount : null
}

function extractCustomerEmail(payload: ShopifyOrderPaidPayload): string {
  // UCP format may have customer email in various places; try common locations
  const fulfillment = payload.fulfillment as Record<string, unknown> | undefined
  const expectations = fulfillment?.expectations as unknown[] | undefined
  if (expectations?.[0]) {
    const dest = (expectations[0] as Record<string, unknown>).destination as Record<string, unknown> | undefined
    if (dest?.email) return String(dest.email)
  }
  return ''
}

async function defaultVerifyHmac(rawBody: string, hmacHeader: string, secret: string): Promise<boolean> {
  const crypto = globalThis.crypto
  if (!crypto?.subtle) {
    throw new Error('Web Crypto API (crypto.subtle) not available; provide verifyHmac in config')
  }
  const encoder = new TextEncoder()
  const keyData = encoder.encode(secret)
  const messageData = encoder.encode(rawBody)
  const key = await crypto.subtle.importKey('raw', keyData, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign'])
  const signature = await crypto.subtle.sign('HMAC', key, messageData)
  const signatureHex = Array.from(new Uint8Array(signature))
    .map(b => b.toString(16).padStart(2, '0'))
    .join('')
  return signatureHex === hmacHeader.toLowerCase()
}

function parseRetryAfter(header: string | null): number | null {
  if (!header) return null
  const seconds = parseInt(header, 10)
  if (!isNaN(seconds)) return seconds * 1000
  const date = new Date(header)
  if (!isNaN(date.getTime())) {
    const diff = date.getTime() - Date.now()
    return diff > 0 ? diff : null
  }
  return null
}

export async function handle(
  payload: ShopifyOrderPaidPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  // Validate required fields
  if (!payload.id) throw new Error('Missing required field: id')
  if (!payload.label) throw new Error('Missing required field: label')
  if (!payload.currency) throw new Error('Missing required field: currency')
  if (!payload.totals || !Array.isArray(payload.totals)) throw new Error('Missing required field: totals')

  const orderId = payload.id
  const orderNumber = payload.label
  const currency = payload.currency

  const totalAmountCents = findTotalAmount(payload, 'total')
  if (totalAmountCents === null) throw new Error('Missing total amount in totals')
  const totalAmount = (totalAmountCents / 100).toFixed(2)

  const customerEmail = extractCustomerEmail(payload)

  const headers = payload._headers ?? {}
  const hmacHeader = headers['x-shopify-hmac-sha256'] ?? headers['X-Shopify-Hmac-SHA256'] ?? ''
  const webhookId = headers['x-shopify-webhook-id'] ?? headers['X-Shopify-Webhook-Id'] ?? ''

  // HMAC verification
  let hmacVerified = false
  const verifyHmac = config.verifyHmac ?? defaultVerifyHmac
  if (payload._rawBody && hmacHeader) {
    hmacVerified = await verifyHmac(payload._rawBody, hmacHeader, config.shopifyClientSecret)
    if (!hmacVerified) throw new Error('HMAC verification failed')
  }

  // Deduplication key: orderId + hmac (fallback to webhookId, then orderId alone)
  const dedupKey = hmacHeader ? `${orderId}:${hmacHeader}` : webhookId ? `${orderId}:${webhookId}` : orderId

  const isDuplicate = await config.dedupStore.has(dedupKey)
  if (isDuplicate) {
    return { airtableRecordIds: [], created: false, updated: false, deduplicated: true }
  }

  // Map fields for Airtable upsert
  const fields = {
    'Order Number': orderNumber,
    'Customer Email': customerEmail,
    'Total': totalAmount,
    'HMAC Digest': hmacHeader,
    'Dedup Order ID': orderId
  }

  const url = `https://api.airtable.com/v0/${config.airtableBaseId}/${config.airtableTableNameOrId}`
  const body = {
    performUpsert: { fieldsToMergeOn: ['Order Number'] },
    records: [{ fields }]
  }

  const fetch = config.fetch ?? globalThis.fetch
  const maxRetries = config.maxRetries ?? 3
  const baseRetryDelayMs = config.baseRetryDelayMs ?? 1000

  let lastError: Error | null = null
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      const response = await fetch(url, {
        method: 'PATCH',
        headers: {
          'Authorization': `Bearer ${config.airtableApiKey}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(body)
      })

      if (response.status >= 200 && response.status < 300) {
        const data = await response.json() as AirtableUpsertResponse
        await config.dedupStore.add(dedupKey)

        const recordIds = data.records?.map(r => r.id) ?? []
        const updated = data.updatedRecords?.flat() ?? []
        const created = data.createdRecords ?? []

        return {
          airtableRecordIds: recordIds,
          created: created.length > 0,
          updated: updated.length > 0,
          deduplicated: false
        }
      }

      const retryable = response.status === 429 || response.status >= 500
      if (!retryable || attempt === maxRetries) {
        const errorText = await response.text()
        throw new Error(`Airtable upsert failed: ${response.status} ${response.statusText} - ${errorText}`)
      }

      const retryAfterMs = parseRetryAfter(response.headers.get('Retry-After'))
      const exponentialMs = baseRetryDelayMs * Math.pow(2, attempt)
      const delayMs = retryAfterMs !== null ? Math.max(retryAfterMs, exponentialMs) : exponentialMs
      await new Promise(resolve => setTimeout(resolve, delayMs))
    } catch (error) {
      lastError = error as Error
      if (attempt === maxRetries) break
      const delayMs = baseRetryDelayMs * Math.pow(2, attempt)
      await new Promise(resolve => setTimeout(resolve, delayMs))
    }
  }

  throw lastError ?? new Error('Airtable upsert failed after retries')
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, ShopifyOrderPaidPayload, DedupStore } from './connector'
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, type RecordedCall } from './fixtures'

// Contract test - must be at top level with title 'contract'
describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const dedupStore: DedupStore = {
      has: vi.fn().mockResolvedValue(false),
      add: vi.fn().mockResolvedValue(undefined)
    }
    const config: ConnectorConfig = {
      shopifyClientSecret: 'test-secret',
      airtableApiKey: 'test-api-key',
      airtableBaseId: 'appTestBase',
      airtableTableNameOrId: 'tblTestTable',
      dedupStore,
      verifyHmac: vi.fn().mockResolvedValue(true),
      fetch
    }
    // SOURCE_EXAMPLE lacks _rawBody and _headers; connector should skip HMAC verification and use orderId for dedup
    const result = await handle(SOURCE_EXAMPLE as unknown as ShopifyOrderPaidPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.deduplicated).toBe(false)
    expect(result.airtableRecordIds).toEqual(['recABC123'])
    expect(result.created).toBe(false)
    expect(result.updated).toBe(true)
  })
})

describe('handle', () => {
  let dedupStore: DedupStore
  let baseConfig: ConnectorConfig
  let basePayload: ShopifyOrderPaidPayload

  beforeEach(() => {
    dedupStore = {
      has: vi.fn().mockResolvedValue(false),
      add: vi.fn().mockResolvedValue(undefined)
    }
    baseConfig = {
      shopifyClientSecret: 'secret',
      airtableApiKey: 'key',
      airtableBaseId: 'appBase',
      airtableTableNameOrId: 'tblTable',
      dedupStore,
      verifyHmac: vi.fn().mockResolvedValue(true),
      maxRetries: 2,
      baseRetryDelayMs: 100
    }
    basePayload = {
      ...SOURCE_EXAMPLE,
      _rawBody: JSON.stringify(SOURCE_EXAMPLE),
      _headers: {
        'X-Shopify-Hmac-SHA256': 'valid-hmac',
        'X-Shopify-Webhook-Id': 'wh-123'
      }
    } as ShopifyOrderPaidPayload
  })

  it('happy path: maps fields correctly and calls Airtable upsert', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.method).toBe('PATCH')
      expect(req.url).toBe('https://api.airtable.com/v0/appBase/tblTable')
      expect(req.headers.get('authorization')).toBe('Bearer key')
      const json = req.json as Record<string, unknown>
      expect(json.performUpsert).toEqual({ fieldsToMergeOn: ['Order Number'] })
      expect(json.records[0].fields).toEqual({
        'Order Number': '#1042',
        'Customer Email': 'jane@example.com',
        'Total': '79.77',
        'HMAC Digest': 'valid-hmac',
        'Dedup Order ID': 'gid://shopify/Order/6252199051413'
      })
      return jsonResponse({
        records: [{ id: 'recNEW1', createdTime: '2024-01-01T00:00:00.000Z', fields: {} }],
        updatedRecords: [],
        createdRecords: ['recNEW1']
      }, 200)
    })

    const result = await handle(basePayload, { ...baseConfig, fetch })
    expect(calls).toHaveLength(1)
    expect(result.airtableRecordIds).toEqual(['recNEW1'])
    expect(result.created).toBe(true)
    expect(result.updated).toBe(false)
    expect(result.deduplicated).toBe(false)
    expect(dedupStore.add).toHaveBeenCalledWith('gid://shopify/Order/6252199051413:valid-hmac')
  })

  it('auth mechanism: sends Bearer token from config', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({
      records: [{ id: 'rec1', createdTime: '', fields: {} }],
      updatedRecords: [['rec1']],
      createdRecords: []
    }, 200))

    await handle(basePayload, { ...baseConfig, airtableApiKey: 'my-api-key', fetch })
    expect(calls[0].headers.get('authorization')).toBe('Bearer my-api-key')
  })

  it('field mapping: converts total from cents to dollars with two decimals', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      const fields = (req.json as Record<string, unknown>).records[0].fields as Record<string, string>
      expect(fields.Total).toBe('79.77')
      return jsonResponse({
        records: [{ id: 'rec1', createdTime: '', fields: {} }],
        updatedRecords: [['rec1']],
        createdRecords: []
      }, 200)
    })

    await handle(basePayload, { ...baseConfig, fetch })
    expect(calls).toHaveLength(1)
  })

  it('missing required field throws descriptive error', async () => {
    const badPayload = { ...basePayload, id: '' } as ShopifyOrderPaidPayload
    await expect(handle(badPayload, baseConfig)).rejects.toThrow('Missing required field: id')
  })

  it('non-2xx target response throws with status and endpoint', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    await expect(handle(basePayload, { ...baseConfig, fetch })).rejects.toThrow('Airtable upsert failed: 401 Unauthorized')
    expect(calls).toHaveLength(1)
  })

  it('deduplicates when dedupStore.has returns true', async () => {
    const dedupStoreDup: DedupStore = {
      has: vi.fn().mockResolvedValue(true),
      add: vi.fn()
    }
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 200))
    const result = await handle(basePayload, { ...baseConfig, dedupStore: dedupStoreDup, fetch })
    expect(result.deduplicated).toBe(true)
    expect(result.airtableRecordIds).toEqual([])
    expect(calls).toHaveLength(0)
    expect(dedupStoreDup.add).not.toHaveBeenCalled()
  })

  it('retries on 429 with exponential backoff and Retry-After header', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (calls.length === 0) {
        return new Response(null, {
          status: 429,
          statusText: 'Too Many Requests',
          headers: { 'Retry-After': '2', 'Content-Type': 'application/json' }
        })
      }
      return jsonResponse({
        records: [{ id: 'rec1', createdTime: '', fields: {} }],
        updatedRecords: [['rec1']],
        createdRecords: []
      }, 200)
    })

    const result = await handle(basePayload, { ...baseConfig, maxRetries: 2, baseRetryDelayMs: 50, fetch })
    expect(calls).toHaveLength(2)
    expect(result.airtableRecordIds).toEqual(['rec1'])
  })

  it('retries on 503 and exhausts retries then throws', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Service Unavailable' }, 503))
    await expect(handle(basePayload, { ...baseConfig, maxRetries: 1, baseRetryDelayMs: 10, fetch }))
      .rejects.toThrow('Airtable upsert failed after retries')
    expect(calls).toHaveLength(2) // initial + 1 retry
  })

  it('uses fallback dedup key when HMAC header missing', async () => {
    const payloadNoHmac = {
      ...basePayload,
      _headers: { 'X-Shopify-Webhook-Id': 'wh-456' }
    } as ShopifyOrderPaidPayload
    const { fetch } = fakeFetch(() => jsonResponse({
      records: [{ id: 'rec1', createdTime: '', fields: {} }],
      updatedRecords: [],
      createdRecords: ['rec1']
    }, 200))

    await handle(payloadNoHmac, { ...baseConfig, fetch })
    expect(dedupStore.has).toHaveBeenCalledWith('gid://shopify/Order/6252199051413:wh-456')
  })

  it('skips HMAC verification when _rawBody missing', async () => {
    const payloadNoRaw = { ...basePayload, _rawBody: undefined } as ShopifyOrderPaidPayload
    const verifyHmac = vi.fn()
    const { fetch } = fakeFetch(() => jsonResponse({
      records: [{ id: 'rec1', createdTime: '', fields: {} }],
      updatedRecords: [],
      createdRecords: ['rec1']
    }, 200))

    await handle(payloadNoRaw, { ...baseConfig, verifyHmac, fetch })
    expect(verifyHmac).not.toHaveBeenCalled()
  })
})

