describe('handle', () => {
  let dedupStore: DedupStore
  let baseConfig: ConnectorConfig
  let basePayload: ShopifyOrderPaidPayload

  beforeEach(() => {
    dedupStore = {
      has: vi.fn().mockResolvedValue(false),
      add: vi.fn().mockResolvedValue(undefined)
    }
    baseConfig = {
      shopifyClientSecret: 'secret',
      airtableApiKey: 'key',
      airtableBaseId: 'appBase',
      airtableTableNameOrId: 'tblTable',
      dedupStore,
      verifyHmac: vi.fn().mockResolvedValue(true),
      maxRetries: 2,
      baseRetryDelayMs: 100
    }
    basePayload = {
      ...SOURCE_EXAMPLE,
      _rawBody: JSON.stringify(SOURCE_EXAMPLE),
      _headers: {
        'X-Shopify-Hmac-SHA256': 'valid-hmac',
        'X-Shopify-Webhook-Id': 'wh-123'
      }
    } as ShopifyOrderPaidPayload
  })

  it('happy path: maps fields correctly and calls Airtable upsert', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.method).toBe('PATCH')
      expect(req.url).toBe('https://api.airtable.com/v0/appBase/tblTable')
      expect(req.headers.get('authorization')).toBe('Bearer key')
      const json = req.json as Record<string, unknown>
      expect(json.performUpsert).toEqual({ fieldsToMergeOn: ['Order Number'] })
      // Use actual values from SOURCE_EXAMPLE
      expect(json.records[0].fields).toEqual({
        'Order Number': '#1042',
        'Customer Email': 'jane@example.com',
        'Total': '79.77',
        'HMAC Digest': 'valid-hmac',
        'Dedup Order ID': 'gid://shopify/Order/6252199051413'
      })
      return jsonResponse({
        records: [{ id: 'recNEW1', createdTime: '2024-01-01T00:00:00.000Z', fields: {} }],
        updatedRecords: [],
        createdRecords: ['recNEW1']
      }, 200)
    })

    const result = await handle(basePayload, { ...baseConfig, fetch })
    expect(calls).toHaveLength(1)
    expect(result.airtableRecordIds).toEqual(['recNEW1'])
    expect(result.created).toBe(true)
    expect(result.updated).toBe(false)
    expect(result.deduplicated).toBe(false)
    expect(dedupStore.add).toHaveBeenCalledWith('gid://shopify/Order/6252199051413:valid-hmac')
  })

  it('auth mechanism: sends Bearer token from config', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({
      records: [{ id: 'rec1', createdTime: '', fields: {} }],
      updatedRecords: [['rec1']],
      createdRecords: []
    }, 200))

    await handle(basePayload, { ...baseConfig, airtableApiKey: 'my-api-key', fetch })
    expect(calls[0].headers.get('authorization')).toBe('Bearer my-api-key')
  })

  it('field mapping: converts total from cents to dollars with two decimals', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      const fields = (req.json as Record<string, unknown>).records[0].fields as Record<string, string>
      expect(fields.Total).toBe('79.77')
      return jsonResponse({
        records: [{ id: 'rec1', createdTime: '', fields: {} }],
        updatedRecords: [['rec1']],
        createdRecords: []
      }, 200)
    })

    await handle(basePayload, { ...baseConfig, fetch })
    expect(calls).toHaveLength(1)
  })

  it('missing required field throws descriptive error', async () => {
    const badPayload = { ...basePayload, id: '' } as ShopifyOrderPaidPayload
    await expect(handle(badPayload, baseConfig)).rejects.toThrow('Missing required field: id')
  })

  it('non-2xx target response throws with status and endpoint', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    await expect(handle(basePayload, { ...baseConfig, fetch })).rejects.toThrow('Airtable upsert failed: 401 Unauthorized')
    expect(calls).toHaveLength(1)
  })

  it('deduplicates when dedupStore.has returns true', async () => {
    const dedupStoreDup: DedupStore = {
      has: vi.fn().mockResolvedValue(true),
      add: vi.fn()
    }
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 200))
    const result = await handle(basePayload, { ...baseConfig, dedupStore: dedupStoreDup, fetch })
    expect(result.deduplicated).toBe(true)
    expect(result.airtableRecordIds).toEqual([])
    expect(calls).toHaveLength(0)
    expect(dedupStoreDup.add).not.toHaveBeenCalled()
  })

  it('retries on 429 with exponential backoff and Retry-After header', async () => {
    let attempt = 0
    const { fetch, calls } = fakeFetch((req) => {
      if (attempt === 0) {
        attempt++
        return new Response(null, {
          status: 429,
          statusText: 'Too Many Requests',
          headers: { 'Retry-After': '2', 'Content-Type': 'application/json' }
        })
      }
      return jsonResponse({
        records: [{ id: 'rec1', createdTime: '', fields: {} }],
        updatedRecords: [['rec1']],
        createdRecords: []
      }, 200)
    })

    const result = await handle(basePayload, { ...baseConfig, maxRetries: 2, baseRetryDelayMs: 50, fetch })
    expect(calls).toHaveLength(2)
    expect(result.airtableRecordIds).toEqual(['rec1'])
  })

  it('retries on 503 and exhausts retries then throws', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Service Unavailable' }, 503))
    await expect(handle(basePayload, { ...baseConfig, maxRetries: 1, baseRetryDelayMs: 10, fetch }))
      .rejects.toThrow('Airtable upsert failed after retries')
    expect(calls).toHaveLength(2) // initial + 1 retry
  })

  it('uses fallback dedup key when HMAC header missing', async () => {
    const payloadNoHmac = {
      ...basePayload,
      _headers: { 'X-Shopify-Webhook-Id': 'wh-456' }
    } as ShopifyOrderPaidPayload
    const { fetch } = fakeFetch(() => jsonResponse({
      records: [{ id: 'rec1', createdTime: '', fields: {} }],
      updatedRecords: [],
      createdRecords: ['rec1']
    }, 200))

    await handle(payloadNoHmac, { ...baseConfig, fetch })
    expect(dedupStore.has).toHaveBeenCalledWith('gid://shopify/Order/6252199051413:wh-456')
  })

  it('skips HMAC verification when _rawBody missing', async () => {
    const payloadNoRaw = { ...basePayload, _rawBody: undefined } as ShopifyOrderPaidPayload
    const verifyHmac = vi.fn()
    const { fetch } = fakeFetch(() => jsonResponse({
      records: [{ id: 'rec1', createdTime: '', fields: {} }],
      updatedRecords: [],
      createdRecords: ['rec1']
    }, 200))

    await handle(payloadNoRaw, { ...baseConfig, verifyHmac, fetch })
    expect(verifyHmac).not.toHaveBeenCalled()
  })
})

