// Test fixtures
const basePayload: ShopifyOrderPaidPayload = {
  id: 'gid://shopify/Order/12345',
  label: '#1042',
  currency: 'USD',
  totals: [{ type: 'total', display_text: '$104.20', amount: 10420 }],
  line_items: [],
  fulfillment: {
    expectations: [{
      destination: { email: 'customer@example.com' }
    }]
  },
  ucp: {},
  _rawBody: '{"id":"gid://shopify/Order/12345","label":"#1042"}',
  _headers: {
    'x-shopify-hmac-sha256': 'abc123',
    'x-shopify-webhook-id': 'wh_123'
  }
}

const baseConfig: ConnectorConfig = {
  shopifyClientSecret: 'test-secret',
  airtableApiKey: 'pat-test',
  airtableBaseId: 'appTestBase',
  airtableTableNameOrId: 'tblTestTable',
  dedupStore: {
    has: vi.fn().mockResolvedValue(false),
    add: vi.fn().mockResolvedValue(undefined)
  },
  verifyHmac: vi.fn().mockResolvedValue(true)
}

describe('handle', () => {
  let dedupStore: DedupStore
  let config: ConnectorConfig

  beforeEach(() => {
    dedupStore = {
      has: vi.fn().mockResolvedValue(false),
      add: vi.fn().mockResolvedValue(undefined)
    }
    config = {
      ...baseConfig,
      dedupStore
    }
  })

  it('happy path: maps fields correctly and calls Airtable upsert', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.method).toBe('PATCH')
      expect(req.url).toBe('https://api.airtable.com/v0/appTestBase/tblTestTable')
      expect(req.headers.get('authorization')).toBe('Bearer pat-test')
      const body = req.json as { performUpsert: { fieldsToMergeOn: string[] }; records: Array<{ fields: Record<string, string> }> }
      expect(body.performUpsert.fieldsToMergeOn).toEqual(['Order Number'])
      expect(body.records[0].fields).toEqual({
        'Order Number': '#1042',
        'Customer Email': 'customer@example.com',
        'Total': '104.20',
        'HMAC Digest': 'abc123',
        'Dedup Order ID': 'gid://shopify/Order/12345'
      })
      return jsonResponse({
        records: [{ id: 'recABC123', createdTime: '2024-01-15T10:30:00.000Z', fields: {} }],
        updatedRecords: [['recABC123']],
        createdRecords: []
      }, 200)
    })

    const result = await handle(basePayload, { ...config, fetch })
    expect(result.airtableRecordIds).toEqual(['recABC123'])
    expect(result.created).toBe(false)
    expect(result.updated).toBe(true)
    expect(result.deduplicated).toBe(false)
    expect(dedupStore.add).toHaveBeenCalledWith('gid://shopify/Order/12345:abc123')
    expect(calls.length).toBe(1)
  })

  it('throws when required field id is missing', async () => {
    const payload = { ...basePayload, id: '' }
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: id')
  })

  it('throws when required field label is missing', async () => {
    const payload = { ...basePayload, label: '' }
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: label')
  })

  it('throws when required field currency is missing', async () => {
    const payload = { ...basePayload, currency: '' }
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: currency')
  })

  it('throws when totals array is missing', async () => {
    const payload = { ...basePayload, totals: undefined as unknown }
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: totals')
  })

  it('throws when total amount is missing from totals', async () => {
    const payload = { ...basePayload, totals: [{ type: 'subtotal', display_text: '$100.00', amount: 10000 }] }
    await expect(handle(payload, config)).rejects.toThrow('Missing total amount in totals')
  })

  it('throws when HMAC verification fails', async () => {
    const configFail = { ...config, verifyHmac: vi.fn().mockResolvedValue(false) }
    await expect(handle(basePayload, configFail)).rejects.toThrow('HMAC verification failed')
  })

  it('deduplicates when dedupStore.has returns true', async () => {
    dedupStore.has = vi.fn().mockResolvedValue(true)
    const result = await handle(basePayload, config)
    expect(result.deduplicated).toBe(true)
    expect(result.airtableRecordIds).toEqual([])
    expect(dedupStore.add).not.toHaveBeenCalled()
  })

  it('uses webhookId for dedup key when HMAC header missing', async () => {
    const payload = { ...basePayload, _headers: { 'x-shopify-webhook-id': 'wh_456' } }
    await handle(payload, config)
    expect(dedupStore.add).toHaveBeenCalledWith('gid://shopify/Order/12345:wh_456')
  })

  it('uses orderId alone for dedup key when both HMAC and webhookId missing', async () => {
    const payload = { ...basePayload, _headers: {} }
    await handle(payload, config)
    expect(dedupStore.add).toHaveBeenCalledWith('gid://shopify/Order/12345')
  })

  it('extracts customer email from fulfillment expectations', async () => {
    const { fetch } = fakeFetch((req) => jsonResponse({
      records: [{ id: 'rec1', createdTime: '', fields: {} }],
      updatedRecords: [],
      createdRecords: ['rec1']
    }, 200))
    await handle(basePayload, { ...config, fetch })
    // Email extraction tested via field mapping in happy path test
  })

  it('non-2xx target response throws with status and endpoint', async () => {
    const { fetch, calls } = fakeFetch((req) => jsonResponse({ error: 'Unauthorized' }, 401))
    await expect(handle(basePayload, { ...config, fetch })).rejects.toThrow('Airtable upsert failed: 401 Unauthorized')
    expect(calls.length).toBe(1)
  })

  it('retries on 503 and succeeds on second attempt', async () => {
    let attempt = 0
    const { fetch, calls } = fakeFetch((req) => {
      attempt++
      if (attempt === 1) {
        return jsonResponse({ error: 'Service Unavailable' }, 503)
      }
      return jsonResponse({
        records: [{ id: 'recRetry', createdTime: '', fields: {} }],
        updatedRecords: [],
        createdRecords: ['recRetry']
      }, 200)
    })

    const result = await handle(basePayload, { ...config, fetch, maxRetries: 3, baseRetryDelayMs: 1 })
    expect(result.airtableRecordIds).toEqual(['recRetry'])
    expect(result.created).toBe(true)
    expect(calls.length).toBe(2)
  })

  it('retries on 503 and exhausts retries then throws', async () => {
    const { fetch, calls } = fakeFetch((req) => jsonResponse({ error: 'Service Unavailable' }, 503))
    await expect(handle(basePayload, { ...config, fetch, maxRetries: 2, baseRetryDelayMs: 1 }))
      .rejects.toThrow('Airtable upsert failed after retries')
    expect(calls.length).toBe(3) // initial + 2 retries
  })

  it('respects Retry-After header in seconds', async () => {
    let attempt = 0
    const { fetch, calls } = fakeFetch((req) => {
      attempt++
      if (attempt === 1) {
        const res = jsonResponse({ error: 'Rate Limited' }, 429)
        res.headers.set('Retry-After', '1')
        return res
      }
      return jsonResponse({
        records: [{ id: 'recRetryAfter', createdTime: '', fields: {} }],
        updatedRecords: [],
        createdRecords: ['recRetryAfter']
      }, 200)
    })

    const result = await handle(basePayload, { ...config, fetch, maxRetries: 3, baseRetryDelayMs: 1000 })
    expect(result.airtableRecordIds).toEqual(['recRetryAfter'])
    expect(calls.length).toBe(2)
  })

  it('respects Retry-After HTTP-date header', async () => {
    let attempt = 0
    const { fetch, calls } = fakeFetch((req) => {
      attempt++
      if (attempt === 1) {
        const future = new Date(Date.now() + 50).toUTCString()
        const res = jsonResponse({ error: 'Rate Limited' }, 429)
        res.headers.set('Retry-After', future)
        return res
      }
      return jsonResponse({
        records: [{ id: 'recRetryDate', createdTime: '', fields: {} }],
        updatedRecords: [],
        createdRecords: ['recRetryDate']
      }, 200)
    })

    const result = await handle(basePayload, { ...config, fetch, maxRetries: 3, baseRetryDelayMs: 1000 })
    expect(result.airtableRecordIds).toEqual(['recRetryDate'])
    expect(calls.length).toBe(2)
  })

  it('uses exponential backoff when Retry-After absent', async () => {
    let attempt = 0
    const { fetch, calls } = fakeFetch((req) => {
      attempt++
      if (attempt <= 2) return jsonResponse({ error: 'Server Error' }, 500)
      return jsonResponse({
        records: [{ id: 'recExp', createdTime: '', fields: {} }],
        updatedRecords: [],
        createdRecords: ['recExp']
      }, 200)
    })

    const result = await handle(basePayload, { ...config, fetch, maxRetries: 3, baseRetryDelayMs: 10 })
    expect(result.airtableRecordIds).toEqual(['recExp'])
    expect(calls.length).toBe(3)
  })

  it('does not retry on 400 Bad Request', async () => {
    const { fetch, calls } = fakeFetch((req) => jsonResponse({ error: 'Bad Request' }, 400))
    await expect(handle(basePayload, { ...config, fetch })).rejects.toThrow('Airtable upsert failed: 400 Bad Request')
    expect(calls.length).toBe(1)
  })

  it('does not retry on 401 Unauthorized', async () => {
    const { fetch, calls } = fakeFetch((req) => jsonResponse({ error: 'Unauthorized' }, 401))
    await expect(handle(basePayload, { ...config, fetch })).rejects.toThrow('Airtable upsert failed: 401 Unauthorized')
    expect(calls.length).toBe(1)
  })

  it('uses default verifyHmac when not provided', async () => {
    const configNoVerify = { ...config, verifyHmac: undefined }
    const { fetch } = fakeFetch((req) => jsonResponse({
      records: [{ id: 'rec1', createdTime: '', fields: {} }],
      updatedRecords: [],
      createdRecords: ['rec1']
    }, 200))
    // Should not throw "Web Crypto API not available" because we mock fetch to succeed
    // and the test payload has _rawBody and hmacHeader so it would call verifyHmac
    // But since we don't have crypto.subtle in test env, we must provide verifyHmac
    // This test just ensures the default function exists and throws appropriately
    await expect(handle(basePayload, { ...configNoVerify, fetch })).rejects.toThrow('Web Crypto API')
  })

  it('returns created=true when createdRecords has entries', async () => {
    const { fetch } = fakeFetch((req) => jsonResponse({
      records: [{ id: 'recNew', createdTime: '', fields: {} }],
      updatedRecords: [],
      createdRecords: ['recNew']
    }, 200))
    const result = await handle(basePayload, { ...config, fetch })
    expect(result.created).toBe(true)
    expect(result.updated).toBe(false)
  })

  it('returns updated=true when updatedRecords has entries', async () => {
    const { fetch } = fakeFetch((req) => jsonResponse({
      records: [{ id: 'recUpd', createdTime: '', fields: {} }],
      updatedRecords: [['recUpd']],
      createdRecords: []
    }, 200))
    const result = await handle(basePayload, { ...config, fetch })
    expect(result.created).toBe(false)
    expect(result.updated).toBe(true)
  })

  it('uses injected fetch from config', async () => {
    const customFetch = vi.fn().mockResolvedValue(jsonResponse({
      records: [{ id: 'recCustom', createdTime: '', fields: {} }],
      updatedRecords: [],
      createdRecords: ['recCustom']
    }, 200))
    const result = await handle(basePayload, { ...config, fetch: customFetch })
    expect(customFetch).toHaveBeenCalled()
    expect(result.airtableRecordIds).toEqual(['recCustom'])
  })

  it('uses default maxRetries (3) when not provided', async () => {
    let attempts = 0
    const { fetch, calls } = fakeFetch((req) => {
      attempts++
      return jsonResponse({ error: 'Server Error' }, 500)
    })
    await expect(handle(basePayload, { ...config, fetch })).rejects.toThrow('Airtable upsert failed after retries')
    expect(calls.length).toBe(4) // initial + 3 retries
  })

  it('uses default baseRetryDelayMs (1000) when not provided', async () => {
    // Just verify it doesn't throw on missing config
    const { fetch } = fakeFetch((req) => jsonResponse({
      records: [{ id: 'recDef', createdTime: '', fields: {} }],
      updatedRecords: [],
      createdRecords: ['recDef']
    }, 200))
    const result = await handle(basePayload, { ...config, fetch })
    expect(result.airtableRecordIds).toEqual(['recDef'])
  })
})

