        records: [{ id: 'recExp', createdTime: '', fields: {} }],
        updatedRecords: [],
        createdRecords: ['recExp']
      }, 200)
    })

    const result = await handle(basePayload, { ...baseConfig, fetch, maxRetries: 3, baseRetryDelayMs: 10 })
    expect(result.airtableRecordIds).toEqual(['recExp'])
    expect(calls.length).toBe(3)
